/// The list with this name.
pub fn list(name: &str) -> Option<&'static ValueList> {
    LISTS.iter().find(|l| l.name == name)
}

/// The native with this name or this alias.
pub fn find(word: &str) -> Option<&'static Native> {
    NATIVES.iter().find(|n| n.name == word || n.alias == word)
}

/// The number that the game writes for a native called by its name or by its alias.
pub fn word_hash(word: &str) -> u32 {
    find(word).map_or_else(|| hash(word), |n| hash(n.name))
}

/// The name that a script shows for each native: the number of the native and its alias.
pub fn display_names() -> std::collections::HashMap<u32, String> {
    NATIVES.iter().map(|n| (hash(n.name), n.alias.to_string())).collect()
}

/// The number that the game writes in a script for the name of a native function (and of a public function).
pub fn hash(name: &str) -> u32 {
    name.bytes().fold(0u32, |value, byte| value.wrapping_mul(0x83) ^ u32::from(byte))
}
